package soroban

import (
	"unsafe"

	"github.com/stellar/rs-soroban-sdk/go/soroban/internal/host"
)

// This file contains helpers used by code generated by soroban-go for
// contract types. They are exported for the generated code, and are not
// intended to be called directly.

// strSlice is the layout the host expects for a slice of strings in linear
// memory: a u32 position followed by a u32 length.
type strSlice struct {
	pos uint32
	len uint32
}

func strSlices(keys []string) []strSlice {
	s := make([]strSlice, len(keys))
	for i, k := range keys {
		s[i] = strSlice{pos: uint32(uintptr(unsafe.Pointer(unsafe.StringData(k)))), len: uint32(len(k))}
	}
	return s
}

// StructToVal returns a map with the keys, which must be sorted, and values.
// It is used by generated code for contract structs.
func StructToVal(keys []string, vals []Val) Val {
	ks := strSlices(keys)
	return Val(host.MapNewFromLinearMemory(slicePtr(ks), slicePtr(vals), u32Val(uint32(len(vals)))))
}

// SparseStructToVal returns a map with the keys, which must be sorted, and
// values, omitting values that are void. It is used by generated code for
// contract events.
func SparseStructToVal(keys []string, vals []Val) Val {
	ks := strSlices(keys)
	return Val(host.SparseMapNewFromLinearMemory(slicePtr(ks), slicePtr(vals), u32Val(uint32(len(vals)))))
}

// StructFromVal unpacks the values of a map with the keys, which must be
// sorted, into vals. Keys missing from the map are set to void, and keys in the
// map that are not in keys cause a trap. It is used by generated code for
// contract structs.
func StructFromVal(v Val, keys []string, vals []Val) {
	v.expectTag(TagMapObject)
	ks := strSlices(keys)
	host.SparseMapUnpackToLinearMemory(uint64(v), slicePtr(ks), slicePtr(vals), u32Val(uint32(len(vals))))
}

// TupleToVal returns a vec of the values. It is used by generated code for
// contract tuple structs and union cases.
func TupleToVal(vals []Val) Val {
	return Val(host.VecNewFromLinearMemory(slicePtr(vals), u32Val(uint32(len(vals)))))
}

// TupleFromVal unpacks a vec into vals, trapping if the vec is not exactly the
// length of vals. It is used by generated code for contract tuple structs.
func TupleFromVal(v Val, vals []Val) {
	v.expectTag(TagVecObject)
	if u32FromRaw(host.VecLen(uint64(v))) != uint32(len(vals)) {
		conversionError()
	}
	if len(vals) > 0 {
		host.VecUnpackToLinearMemory(uint64(v), slicePtr(vals), u32Val(uint32(len(vals))))
	}
}

// UnionFromVal decodes the case of a union encoded as a vec whose first element
// is the case name symbol. It returns the index of the case in names and the
// vec. It traps if the value is not a vec, is empty, or the case is unknown.
// It is used by generated code for contract unions.
func UnionFromVal(v Val, names []string) (uint32, Vec[Val]) {
	v.expectTag(TagVecObject)
	vec := Vec[Val]{obj: v}
	if vec.Len() == 0 {
		conversionError()
	}
	sym := Val(host.VecGet(uint64(v), u32Val(0)))
	if t := sym.Tag(); t != TagSymbolSmall && t != TagSymbolObject {
		conversionError()
	}
	ks := strSlices(names)
	idx := u32FromRaw(host.SymbolIndexInLinearMemory(uint64(sym), slicePtr(ks), u32Val(uint32(len(ks)))))
	return idx, vec
}

// UnionCaseFromVal unpacks the fields of a union case, trapping if the number
// of fields is not exactly the length of vals. It is used by generated code for
// contract unions.
func UnionCaseFromVal(vec Vec[Val], vals []Val) {
	if vec.Len() != uint32(len(vals))+1 {
		conversionError()
	}
	for i := range vals {
		vals[i] = Val(host.VecGet(uint64(vec.obj), u32Val(uint32(i)+1)))
	}
}

// UnionToVal returns the vec encoding of a union case with the name and
// fields. It is used by generated code for contract unions.
func UnionToVal(name string, fields ...Val) Val {
	vals := make([]Val, len(fields)+1)
	vals[0] = SymbolFromStr(name).ToVal()
	copy(vals[1:], fields)
	return TupleToVal(vals)
}

// EnumToVal returns the U32Val for an integer enum. It is used by generated
// code for contract enums.
func EnumToVal(x uint32) Val { return valFromU32(x) }

// EnumFromVal returns the integer of a U32Val for an integer enum. It is used
// by generated code for contract enums.
func EnumFromVal(v Val) uint32 {
	v.expectTag(TagU32Val)
	return v.Major()
}

// ContractErrorFromVal returns the code of a contract Error Val, trapping if
// the Val is not a contract error. It is used by generated code for contract
// errors.
func ContractErrorFromVal(v Val) uint32 {
	var e Error
	e.FromVal(v)
	if e.Type != ErrorTypeContract {
		conversionError()
	}
	return e.Code
}

// ConversionError traps with a conversion error. It is used by generated code.
func ConversionError() { conversionError() }

// Conversions of Go primitives, used by generated code to avoid boxing values
// in interfaces.

func ValFromBool(x bool) Val     { return valFromBool(x) }
func ValFromU32(x uint32) Val    { return valFromU32(x) }
func ValFromI32(x int32) Val     { return valFromI32(x) }
func ValFromU64(x uint64) Val    { return valFromU64(x) }
func ValFromI64(x int64) Val     { return valFromI64(x) }
func BoolFromVal(v Val) (x bool) { FromValInto(&x, v); return }
func U32FromVal(v Val) uint32    { v.expectTag(TagU32Val); return v.Major() }
func I32FromVal(v Val) int32     { v.expectTag(TagI32Val); return int32(v.Major()) }
func U64FromVal(v Val) uint64    { return valToU64(v) }
func I64FromVal(v Val) int64     { return valToI64(v) }
